import{ashramData,eightLimbs}from"./data.js";(()=>{const e=document.getElementById("eight-limbs-grid"),a=document.getElementById("ashrams-list");e.innerHTML="",eightLimbs.forEach((a,t)=>{const n=document.createElement("article");n.className="limb-card",n.innerHTML=`\n        <h3>\n          ${t+1}. ${a.name}\n          <span class="limb-meaning">(${a.meaning})</span>\n        </h3>\n        <p>${a.description}</p>\n      `,e.appendChild(n)}),a.innerHTML="",ashramData.forEach(e=>{const t=document.createElement("article");t.className="ashram-card";const n=document.createElement("div");n.className="ashram-img";const i=document.createElement("img");i.src=e.image,i.alt=`Photo of ${e.name}`,i.loading="lazy",i.onerror=()=>{i.src="data:image/svg+xml;charset=UTF-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22400%22%20height%3D%22200%22%20viewBox%3D%220%200%20400%20200%22%3E%3Crect%20fill%3D%22%239CAF88%22%20width%3D%22400%22%20height%3D%22200%22%2F%3E%3Ctext%20fill%3D%22%232A5A5B%22%20font-family%3D%22sans-serif%22%20font-size%3D%2216%22%20dy%3D%228%22%20font-weight%3D%22bold%22%20x%3D%2250%25%22%20y%3D%2250%25%22%20text-anchor%3D%22middle%22%3EImage%20Unavailable%3C%2Ftext%3E%3C%2Fsvg%3E"},n.appendChild(i);const s=document.createElement("div");s.className="ashram-content",s.innerHTML=`\n        <h3>${e.name}</h3>\n        <p class="ashram-meta">${e.location}, ${e.state} | ${e.tradition}</p>\n        <p>${e.description}</p>\n      `,t.appendChild(n),t.appendChild(s),a.appendChild(t)})})();